208: LIBDE265_API de265_error de265_init()
209: {
210:   std::lock_guard<std::mutex> lock(de265_init_mutex());
211: 
212:   de265_init_count++;
213: 
214:   if (de265_init_count > 1) {
215:     // we are not the first -> already initialized
216: 
217:     return DE265_OK;
218:   }
219: 
220: 
221:   // do initializations
222: 
223:   init_scan_orders();
224:   pps_scan_cache_init();
225: 
226:   if (!alloc_and_init_significant_coeff_ctxIdx_lookupTable()) {
227:     pps_scan_cache_free();
228:     de265_init_count--;
229:     return DE265_ERROR_LIBRARY_INITIALIZATION_FAILED;
230:   }
231: 
232:   return DE265_OK;
233: }
234: 
235: LIBDE265_API de265_error de265_free()
236: {
237:   std::lock_guard<std::mutex> lock(de265_init_mutex());
238: 
239:   if (de265_init_count<=0) {
240:     return DE265_ERROR_LIBRARY_NOT_INITIALIZED;
241:   }
242: 
243:   de265_init_count--;
244: 
245:   if (de265_init_count==0) {
246:     free_significant_coeff_ctxIdx_lookupTable();
247:     pps_scan_cache_free();
248:   }
249: 
250:   return DE265_OK;
251: }
