304: #ifndef LIBDE265_DISABLE_DEPRECATED
305: LIBDE265_API de265_error de265_decode_data(de265_decoder_context* de265ctx,
306:                                            const void* data8, int len)
307: {
308:   //decoder_context* ctx = reinterpret_cast<decoder_context*>(de265ctx);
309:   de265_error err;
310:   if (len > 0) {
311:     err = de265_push_data(de265ctx, data8, len, 0, nullptr);
312:   } else {
313:     err = de265_flush_data(de265ctx);
314:   }
315:   if (err != DE265_OK) {
316:     return err;
317:   }
318: 
319:   int more = 0;
320:   do {
321:     err = de265_decode(de265ctx, &more);
322:     if (err != DE265_OK) {
323:         more = 0;
324:     }
325: 
326:     switch (err) {
327:     case DE265_ERROR_WAITING_FOR_INPUT_DATA:
328:       // ignore error (didn't exist in 0.4 and before)
329:       err = DE265_OK;
330:       break;
331:     default:
332:       break;
333:     }
334:   } while (more);
335:   return err;
336: }
337: #endif
