451: LIBDE265_API void de265_release_next_picture(de265_decoder_context* de265ctx)
452: {
453:   decoder_context* ctx = reinterpret_cast<decoder_context*>(de265ctx);
454: 
455:   // no active output picture -> ignore release request
456: 
457:   if (ctx->num_pictures_in_output_queue()==0) { return; }
458: 
459:   de265_image* next_image = ctx->get_next_picture_in_output_queue();
460: 
461:   loginfo(LogDPB, "release DPB with POC=%d\n",next_image->PicOrderCntVal);
462: 
463:   next_image->PicOutputFlag = false;
464: 
465:   // TODO: actually, we want to release it here, but we cannot without breaking API
466:   // compatibility, because get_next_picture calls this immediately. Hence, we release
467:   // images while scanning for available slots in the DPB.
468:   // if (next_image->can_be_released()) { next_image->release(); }
469: 
470:   // pop output queue
471: 
472:   ctx->pop_next_picture_in_output_queue();
473: }
