124: {
125:   while(true) {
126: 
127:     thread_task* task = nullptr;
128: 
129:     {
130:       std::unique_lock<std::mutex> lock(pool->mutex);
131: 
132:       // wait until we can pick a task or until the pool has been stopped
133: 
134:       for (;;) {
135:         // end waiting if thread-pool has been stopped or we have a task to execute
136: 
137:         if (pool->stopped || pool->tasks.size()>0) {
